  const assignedPortion = dayDetails?.assignedPortion || `\u0627\u0644\u0645\u0642\u0631\u0631 \u0627\u0644\u064A\u0648\u0645\u064A \u0644\u0644\u064A\u0648\u0645 ${dayNum}`;
